import React, { useState } from 'react';
import { MessageSquareText, Mic, Play, Pause } from 'lucide-react';

export default function FloatingWidgets() {
  const [isPlayingAudio, setIsPlayingAudio] = useState(true);

  return (
    <>
      {/* 1. Top-Left Floating Notification Card */}
      <div className="absolute top-10 -left-6 sm:-left-12 z-20 bg-white/95 backdrop-blur-md p-3.5 rounded-2xl shadow-xl shadow-sky-950/10 border border-slate-100/90 flex items-center gap-3 animate-float hover:scale-105 transition-all duration-300">
        <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-[#006699] to-sky-500 flex items-center justify-center text-white shadow-md shadow-sky-900/20">
          <MessageSquareText className="w-5 h-5" />
        </div>
        <div>
          <h4 className="text-xs font-bold text-slate-800 leading-tight">New Message</h4>
          <p className="text-[11px] font-medium text-sky-600">From Shruti</p>
        </div>
      </div>

      {/* 2. Bottom-Left Floating Audio Waveform Card */}
      <div className="absolute bottom-16 -left-8 sm:-left-16 z-20 bg-white/95 backdrop-blur-md px-4 py-3 rounded-2xl shadow-xl shadow-sky-950/10 border border-slate-100/90 flex items-center gap-3 animate-float-delayed">
        <button
          onClick={() => setIsPlayingAudio(!isPlayingAudio)}
          className="w-8 h-8 rounded-full bg-sky-50 border border-sky-100 flex items-center justify-center text-[#006699] hover:bg-sky-100 transition-all active:scale-95 cursor-pointer"
          title={isPlayingAudio ? 'Pause Audio' : 'Play Audio'}
        >
          {isPlayingAudio ? <Pause className="w-3.5 h-3.5" /> : <Play className="w-3.5 h-3.5 ml-0.5" />}
        </button>

        {/* Live Audio Equalizer Waveform Bars */}
        <div className="flex items-center gap-1.5 h-6 w-24">
          <span className={`w-1 bg-[#006699] rounded-full ${isPlayingAudio ? 'animate-sound-bar-1' : 'h-2'}`}></span>
          <span className={`w-1 bg-[#006699] rounded-full ${isPlayingAudio ? 'animate-sound-bar-2' : 'h-4'}`}></span>
          <span className={`w-1 bg-[#006699] rounded-full ${isPlayingAudio ? 'animate-sound-bar-3' : 'h-1'}`}></span>
          <span className={`w-1 bg-[#006699] rounded-full ${isPlayingAudio ? 'animate-sound-bar-4' : 'h-3'}`}></span>
          <span className={`w-1 bg-sky-400 rounded-full ${isPlayingAudio ? 'animate-sound-bar-2' : 'h-2'}`}></span>
          <span className={`w-1 bg-slate-300 rounded-full ${isPlayingAudio ? 'animate-sound-bar-1' : 'h-1'}`}></span>
          <span className={`w-1 bg-slate-300 rounded-full ${isPlayingAudio ? 'animate-sound-bar-3' : 'h-3'}`}></span>
        </div>
      </div>

      {/* 3. Right Floating Status Badge */}
      <div className="absolute top-1/2 -right-4 sm:-right-10 transform -translate-y-1/2 z-20 bg-white/95 backdrop-blur-md px-4 py-2 rounded-full shadow-lg shadow-sky-950/10 border border-slate-100/90 flex items-center gap-2.5 hover:scale-105 transition-all duration-300">
        <span className="relative flex h-3 w-3">
          <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75"></span>
          <span className="relative inline-flex rounded-full h-3 w-3 bg-emerald-500"></span>
        </span>
        <span className="text-xs font-semibold text-slate-800">Shruti Live Now</span>
      </div>
    </>
  );
}
